const raw = $json.output;

let data;

try {
  data = JSON.parse(raw);
} catch (error) {
  throw new Error(
    'AI вернул ответ не в формате JSON. Получено: ' + raw
  );
}

if (!data.category) {
  throw new Error('В ответе AI отсутствует поле category');
}

if (!data.priority) {
  throw new Error('В ответе AI отсутствует поле priority');
}

if (!data.summary) {
  throw new Error('В ответе AI отсутствует поле summary');
}

return [{ json: data }];

